/**
 * Write text to the clipboard. Uses the async Clipboard API and falls back to a hidden textarea
 * where that API is missing or refused (plain-http pages, some webviews and iframes).
 */
export async function writeClipboard(text: string): Promise<boolean> {
  try {
    if (typeof navigator !== 'undefined' && navigator.clipboard?.writeText) {
      await navigator.clipboard.writeText(text);
      return true;
    }
  } catch {
    // Refused (insecure context, permissions policy): try the legacy path below.
  }
  return legacyCopy(text);
}

function legacyCopy(text: string): boolean {
  if (typeof document === 'undefined' || typeof document.execCommand !== 'function') return false;
  const active = document.activeElement instanceof HTMLElement ? document.activeElement : null;
  const area = document.createElement('textarea');
  area.value = text;
  area.setAttribute('readonly', '');
  area.setAttribute('aria-hidden', 'true');
  area.style.cssText =
    'position:fixed;top:0;left:0;width:1px;height:1px;opacity:0;pointer-events:none';
  document.body.append(area);
  area.select();
  let ok = false;
  try {
    ok = document.execCommand('copy');
  } catch {
    ok = false;
  }
  area.remove();
  active?.focus({ preventScroll: true });
  return ok;
}

@layer hj.components {
  /* Customise: --hj-code-block-max-height · --hj-code-block-bg · --hj-code-block-font-size ·
     token colours --hj-code-block-{keyword,string,number,constant,function,type,tag,attr,property,variable,comment,punct} */
  .hj-code-block {
    position: relative;
    margin: 0;
    overflow: hidden;
    border-radius: var(--hj-radius-md);
    corner-shape: var(--hj-corner-shape, round);
    background: var(--hj-code-block-bg, var(--hj-surface));
    box-shadow: inset 0 0 0 1px var(--hj-line);
    color: var(--hj-fg);
    font-family: var(--hj-font-sans);
    transition: box-shadow var(--hj-dur-base) var(--hj-ease-out);
  }
  /* A copied block answers with a brief success hairline. */
  .hj-code-block[data-copied] {
    box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--hj-success) 55%, var(--hj-line));
  }
  .hj-code-block-header {
    display: flex;
    align-items: center;
    gap: calc(10px * var(--hj-density));
    min-height: calc(40px * var(--hj-density-size));
    padding: 0 calc(6px * var(--hj-density)) 0 calc(14px * var(--hj-density));
    border-bottom: 1px solid var(--hj-line);
  }
  .hj-code-block-language {
    font: 500 11px / 1 var(--hj-font-mono);
    letter-spacing: 0.04em;
    text-transform: lowercase;
    color: var(--hj-fg-mute);
  }
  .hj-code-block-filename {
    min-width: 0;
    overflow: hidden;
    white-space: nowrap;
    text-overflow: ellipsis;
    direction: rtl;
    text-align: left;
    font: 500 12px / 1 var(--hj-font-mono);
    color: var(--hj-fg-dim);
  }
  .hj-code-block-actions {
    display: flex;
    align-items: center;
    gap: 2px;
    margin-left: auto;
  }

  .hj-code-block-button {
    position: relative;
    display: inline-flex;
    align-items: center;
    gap: calc(6px * var(--hj-density));
    height: 28px;
    min-width: 28px;
    padding: 0 calc(8px * var(--hj-density));
    border: 0;
    border-radius: var(--hj-radius-pill);
    background: transparent;
    color: var(--hj-fg-mute);
    font: 600 12px / 1 var(--hj-font-sans);
    cursor: pointer;
    transition:
      background-color var(--hj-dur-fast) var(--hj-ease-out),
      color var(--hj-dur-fast) var(--hj-ease-out),
      transform var(--hj-dur-snappy) var(--hj-ease-snappy);
  }
  .hj-code-block-button::before {
    content: '';
    position: absolute;
    inset: -8px -2px;
  }
  .hj-code-block-button:hover {
    background: color-mix(in srgb, var(--hj-fg) 7%, transparent);
    color: var(--hj-fg);
  }
  .hj-code-block-button:active {
    transform: scale(var(--hj-press));
    transition-duration: 70ms;
  }
  .hj-code-block-button[data-pressed] {
    background: var(--hj-accent-soft);
    color: var(--hj-accent);
  }
  .hj-code-block-button > svg {
    width: 15px;
    height: 15px;
  }
  .hj-code-block-button[data-copied] {
    color: var(--hj-success);
  }
  .hj-code-block-glyphs {
    display: inline-grid;
    font-size: 15px;
    line-height: 0;
  }
  .hj-code-block-glyph {
    grid-area: 1 / 1;
    display: grid;
    transition:
      opacity var(--hj-dur-fast) var(--hj-ease-out),
      transform var(--hj-dur-snappy-settle) var(--hj-ease-snappy-settle);
  }
  .hj-code-block-glyph svg {
    width: 1em;
    height: 1em;
  }
  .hj-code-block-button:not([data-copied]) .hj-code-block-glyph[data-glyph='done'],
  .hj-code-block-button[data-copied] .hj-code-block-glyph[data-glyph='copy'] {
    opacity: 0;
    transform: scale(0.7);
  }
  /* The check draws itself. */
  .hj-code-block-check {
    stroke-dasharray: 1;
    stroke-dashoffset: 1;
  }
  .hj-code-block-button[data-copied] .hj-code-block-check {
    stroke-dashoffset: 0;
    transition: stroke-dashoffset var(--hj-dur-slow) var(--hj-ease-out) 60ms;
  }
  /* Copy as a direct child of Root floats over the code's top-right corner. */
  .hj-code-block > .hj-code-block-button {
    position: absolute;
    z-index: 1;
    top: calc(8px * var(--hj-density));
    right: calc(8px * var(--hj-density));
    background: var(--hj-code-block-bg, var(--hj-surface));
    box-shadow: inset 0 0 0 1px var(--hj-line);
  }
  .hj-code-block > .hj-code-block-button:hover {
    background: color-mix(in srgb, var(--hj-fg) 7%, var(--hj-code-block-bg, var(--hj-surface)));
  }
  @media (hover: hover) {
    .hj-code-block > .hj-code-block-button {
      opacity: 0;
      transition:
        opacity var(--hj-dur-fast) var(--hj-ease-out),
        background-color var(--hj-dur-fast) var(--hj-ease-out),
        color var(--hj-dur-fast) var(--hj-ease-out),
        transform var(--hj-dur-snappy) var(--hj-ease-snappy);
    }
    .hj-code-block:hover > .hj-code-block-button,
    .hj-code-block:focus-within > .hj-code-block-button,
    .hj-code-block > .hj-code-block-button[data-copied] {
      opacity: 1;
    }
  }

  .hj-code-block-code {
    margin: 0;
    max-height: var(--hj-code-block-max-height, 420px);
    padding: calc(14px * var(--hj-density)) calc(16px * var(--hj-density));
    overflow: auto;
    outline: none;
    font: 400 var(--hj-code-block-font-size, 12.5px) / 1.65 var(--hj-font-mono);
    color: var(--hj-fg);
    tab-size: 2;
    white-space: pre;
  }
  .hj-code-block-code:focus-visible {
    box-shadow: inset 0 0 0 2px var(--hj-focus);
  }
  .hj-code-block[data-wrap] .hj-code-block-code {
    white-space: pre-wrap;
    overflow-wrap: anywhere;
  }
  .hj-code-block-code > code {
    font: inherit;
    counter-reset: hj-line;
  }
  .hj-code-block-line {
    display: block;
    padding-left: 3.2em;
    text-indent: -3.2em;
  }
  .hj-code-block-line::before {
    counter-increment: hj-line;
    content: counter(hj-line);
    display: inline-block;
    width: 2.2em;
    margin-right: 1em;
    text-align: right;
    text-indent: 0;
    color: var(--hj-fg-mute);
    opacity: 0.7;
    user-select: none;
    font-variant-numeric: tabular-nums;
  }

  /* Syntax: hanji's data hues, pulled 20% toward the ink so small mono type keeps its contrast on
     every paper. Each kind reads a --hj-code-block-<kind> hook first. */
  .hj-code-block-token[data-token='keyword'] {
    color: var(--hj-code-block-keyword, color-mix(in oklab, var(--hj-data-4) 80%, var(--hj-fg)));
  }
  .hj-code-block-token[data-token='string'] {
    color: var(--hj-code-block-string, color-mix(in oklab, var(--hj-data-3) 80%, var(--hj-fg)));
  }
  .hj-code-block-token[data-token='number'] {
    color: var(--hj-code-block-number, color-mix(in oklab, var(--hj-data-2) 80%, var(--hj-fg)));
  }
  .hj-code-block-token[data-token='constant'] {
    color: var(--hj-code-block-constant, color-mix(in oklab, var(--hj-data-2) 80%, var(--hj-fg)));
  }
  .hj-code-block-token[data-token='function'] {
    color: var(--hj-code-block-function, color-mix(in oklab, var(--hj-data-1) 80%, var(--hj-fg)));
  }
  .hj-code-block-token[data-token='type'] {
    color: var(--hj-code-block-type, color-mix(in oklab, var(--hj-data-6) 80%, var(--hj-fg)));
  }
  .hj-code-block-token[data-token='tag'] {
    color: var(--hj-code-block-tag, color-mix(in oklab, var(--hj-data-1) 80%, var(--hj-fg)));
  }
  .hj-code-block-token[data-token='attr'] {
    color: var(--hj-code-block-attr, color-mix(in oklab, var(--hj-data-5) 80%, var(--hj-fg)));
  }
  .hj-code-block-token[data-token='property'] {
    color: var(--hj-code-block-property, color-mix(in oklab, var(--hj-data-1) 80%, var(--hj-fg)));
  }
  .hj-code-block-token[data-token='variable'] {
    color: var(--hj-code-block-variable, color-mix(in oklab, var(--hj-data-5) 80%, var(--hj-fg)));
  }
  .hj-code-block-token[data-token='comment'] {
    color: var(--hj-code-block-comment, var(--hj-fg-mute));
  }
  .hj-code-block-token[data-token='punct'] {
    color: var(--hj-code-block-punct, var(--hj-fg-dim));
  }

  /* Snippet: one line, copy-first. */
  .hj-code-block-snippet {
    --_h: var(--hj-code-block-snippet-height, calc(40px * var(--hj-density-size)));
    position: relative;
    display: inline-flex;
    align-items: center;
    max-width: 100%;
    min-width: 0;
    height: var(--_h);
    padding: 0 calc(6px * var(--hj-density)) 0 calc(14px * var(--hj-density));
    border-radius: var(--hj-radius-sm);
    corner-shape: var(--hj-corner-shape, round);
    background: var(--hj-code-block-bg, var(--hj-surface));
    box-shadow: inset 0 0 0 1px var(--hj-line);
    font: 400 var(--hj-code-block-font-size, 12.5px) / 1 var(--hj-font-mono);
    color: var(--hj-fg);
    transition: box-shadow var(--hj-dur-base) var(--hj-ease-out);
  }
  .hj-code-block-snippet[data-copied] {
    box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--hj-success) 55%, var(--hj-line));
  }
  .hj-code-block-prompt {
    flex: none;
    margin-right: 1ch;
    color: var(--hj-fg-mute);
    user-select: none;
  }
  /* One click selects the whole line; long lines scroll under a fade instead of wrapping. */
  .hj-code-block-snippet-code {
    flex: 1 1 auto;
    min-width: 0;
    padding: calc(10px * var(--hj-density)) calc(14px * var(--hj-density))
      calc(10px * var(--hj-density)) 0;
    overflow-x: auto;
    font: inherit;
    white-space: pre;
    user-select: all;
    scrollbar-width: none;
    mask-image: linear-gradient(to right, black calc(100% - 14px), transparent);
  }
  .hj-code-block-snippet-code::-webkit-scrollbar {
    display: none;
  }
  .hj-code-block-snippet > .hj-code-block-button {
    flex: none;
  }
}

'use client';
import { Button as BaseButton } from '@base-ui/react/button';
import { Toggle as BaseToggle } from '@base-ui/react/toggle';
import { useRender } from '@base-ui/react/use-render';
import * as React from 'react';

import type { HanjiConfig } from '../../system/config.tsx';
import { elementPart } from '../../system/part.tsx';
import type { ElementPartProps } from '../../system/part.tsx';
import { cls, flag } from '../../system/slot.ts';
import { useSlot } from '../../system/use-slot.ts';
import { writeClipboard } from './clipboard.ts';
import { tokenize } from './highlight.ts';
import type { TokenKind } from './highlight.ts';

/** One run of code and how to paint it. */
export interface HighlightToken {
  text: string;
  /** Painted from the theme (`--hj-code-block-<kind>`). The built-in highlighter sets this. */
  kind?: TokenKind | null;
  /** For adapters that bring their own classes (Prism, highlight.js). */
  className?: string;
  /** For adapters that bring their own colours (Shiki's `codeToTokens`). */
  style?: React.CSSProperties;
}

/**
 * Turns code into tokens. Returning tokens rather than elements keeps line numbers, wrapping and
 * copy working with any engine.
 */
export type Highlighter = (code: string, language: string | undefined) => readonly HighlightToken[];

const VISUALLY_HIDDEN: React.CSSProperties = {
  position: 'absolute',
  width: 1,
  height: 1,
  overflow: 'hidden',
  clip: 'rect(0 0 0 0)',
  whiteSpace: 'nowrap',
};
const SHELLS = new Set(['sh', 'bash', 'zsh', 'shell', 'console']);

/** Copied state that lasts 1.6 s and restarts on every copy. */
function useCopy(onCopy?: (text: string) => void): {
  copied: boolean;
  copy: (text: string) => void;
} {
  const [tick, setTick] = React.useState(0);
  React.useEffect(() => {
    if (!tick) return;
    const id = window.setTimeout(() => setTick(0), 1600);
    return () => window.clearTimeout(id);
  }, [tick]);
  const copy = React.useCallback(
    (text: string) => {
      void writeClipboard(text).then((ok) => {
        if (!ok) return;
        setTick((t) => t + 1);
        onCopy?.(text);
      });
    },
    [onCopy],
  );
  return { copied: tick > 0, copy };
}

function useTokens(
  code: string | undefined,
  language: string | undefined,
  highlight: boolean | Highlighter,
): readonly HighlightToken[] | null {
  return React.useMemo(() => {
    if (code === undefined) return null;
    if (highlight === false) return [{ text: code }];
    return highlight === true ? tokenize(code, language) : highlight(code, language);
  }, [code, language, highlight]);
}

function paint(t: HighlightToken, key: number, styled: boolean): React.ReactNode {
  if (!t.kind && !t.className && !t.style) return t.text;
  return (
    <span
      key={key}
      className={
        [styled ? 'hj-code-block-token' : null, t.className].filter(Boolean).join(' ') || undefined
      }
      data-token={t.kind ?? undefined}
      style={t.style}
    >
      {t.text}
    </span>
  );
}

/** Split tokens at newlines; a trailing newline doesn't make an empty last line. */
function toLines(tokens: readonly HighlightToken[]): HighlightToken[][] {
  const lines: HighlightToken[][] = [[]];
  for (const t of tokens) {
    const parts = t.text.split('\n');
    for (let i = 0; i < parts.length; i++) {
      if (i > 0) lines.push([]);
      const text = parts[i] as string;
      if (text) (lines.at(-1) as HighlightToken[]).push(parts.length === 1 ? t : { ...t, text });
    }
  }
  if (lines.length > 1 && lines.at(-1)?.length === 0) lines.pop();
  return lines;
}

function CopyGlyph({
  styled,
  config,
}: {
  styled: boolean;
  config: HanjiConfig;
}): React.ReactElement {
  return (
    <span className={styled ? 'hj-code-block-glyphs' : undefined} aria-hidden="true">
      <span className={styled ? 'hj-code-block-glyph' : undefined} data-glyph="copy">
        {config.icons.copy}
      </span>
      <span className={styled ? 'hj-code-block-glyph' : undefined} data-glyph="done">
        <svg
          viewBox="0 0 24 24"
          width="1em"
          height="1em"
          fill="none"
          stroke="currentColor"
          strokeWidth={1.75}
          strokeLinecap="round"
          strokeLinejoin="round"
        >
          <path
            d="M20 6 9 17l-5-5"
            pathLength={1}
            className={styled ? 'hj-code-block-check' : undefined}
          />
        </svg>
      </span>
    </span>
  );
}

interface CodeBlockContextValue {
  wrap: boolean;
  setWrap: (wrap: boolean) => void;
  lineNumbers: boolean;
  language: string | undefined;
  copied: boolean;
  /** Copy `text`, or the block's code. */
  copy: (text?: string) => void;
  /** Callback ref for the <code> element. */
  setCode: (el: HTMLElement | null) => void;
}
const CodeBlockContext = React.createContext<CodeBlockContextValue | null>(null);

function useCodeBlock(part: string): CodeBlockContextValue {
  const ctx = React.useContext(CodeBlockContext);
  if (!ctx) throw new Error(`[hanji] CodeBlock.${part} must be inside CodeBlock.Root`);
  return ctx;
}

/** Props hanji adds to the Root. */
export interface RootOwnProps {
  /** Language for highlighting and the Language part, e.g. `tsx`, `css`, `json`, `sh`. */
  language?: string;
  /** Soft-wrap long lines (controlled). */
  wrap?: boolean;
  /** @default false */
  defaultWrap?: boolean;
  onWrapChange?: (wrap: boolean) => void;
  /** Number the lines. Works with the `code` prop of CodeBlock.Code. @default false */
  lineNumbers?: boolean;
  /** Called with the text after every successful copy (button or ⌘C). */
  onCopy?: (text: string) => void;
}
export interface RootProps
  extends RootOwnProps, Omit<React.ComponentProps<'figure'>, 'className' | 'onCopy'> {
  className?: string;
  render?: useRender.RenderProp;
}

/**
 * Code in a reply or doc: a header (language, filename, copy, wrap) over a scrollable block,
 * highlighted by a small built-in highlighter or your own.
 */
export function Root(props: RootProps): React.ReactElement {
  const [
    config,
    {
      language,
      wrap: wrapProp,
      defaultWrap = false,
      onWrapChange,
      lineNumbers = false,
      onCopy,
      className,
      render,
      children,
      ...rest
    },
  ] = useSlot('CodeBlock.Root', props);
  const [inner, setInner] = React.useState(defaultWrap);
  const wrap = wrapProp ?? inner;
  const codeEl = React.useRef<HTMLElement | null>(null);
  const controlled = wrapProp !== undefined;
  const setWrap = React.useCallback(
    (next: boolean) => {
      if (!controlled) setInner(next);
      onWrapChange?.(next);
    },
    [controlled, onWrapChange],
  );
  const setCode = React.useCallback((el: HTMLElement | null) => {
    codeEl.current = el;
  }, []);
  const { copied, copy: write } = useCopy(onCopy);
  const copy = React.useCallback(
    (text?: string) => write(text ?? codeEl.current?.textContent ?? ''),
    [write],
  );
  const ctx = React.useMemo(
    () => ({ wrap, setWrap, lineNumbers, language, copied, copy, setCode }),
    [wrap, setWrap, lineNumbers, language, copied, copy, setCode],
  );
  return useRender({
    render,
    defaultTagName: 'figure',
    props: {
      ...rest,
      'data-wrap': flag(wrap),
      'data-line-numbers': flag(lineNumbers),
      'data-copied': flag(copied),
      className: cls(config, 'CodeBlock.Root', 'hj-code-block', className) as string | undefined,
      children: (
        <CodeBlockContext.Provider value={ctx}>
          {children}
          <span style={VISUALLY_HIDDEN} aria-live="polite">
            {copied ? config.strings.copied : ''}
          </span>
        </CodeBlockContext.Provider>
      ),
    },
  });
}

export const Header: (props: ElementPartProps<'div'>) => React.ReactElement = elementPart(
  'div',
  'CodeBlock.Header',
  'hj-code-block-header',
);

/** The language, e.g. `tsx`. Shows the Root's `language` when it has no children. */
export function Language(props: ElementPartProps<'span'>): React.ReactElement {
  const [config, { render, className, children, ...rest }] = useSlot('CodeBlock.Language', props);
  const ctx = React.useContext(CodeBlockContext);
  return useRender({
    render,
    defaultTagName: 'span',
    props: {
      ...rest,
      className: cls(config, 'CodeBlock.Language', 'hj-code-block-language', className) as
        | string
        | undefined,
      children: children ?? ctx?.language,
    },
  });
}

/** A file path, truncated from the start. */
export const Filename: (props: ElementPartProps<'span'>) => React.ReactElement = elementPart(
  'span',
  'CodeBlock.Filename',
  'hj-code-block-filename',
);
/** Right-aligned actions in the header. */
export const Actions: (props: ElementPartProps<'div'>) => React.ReactElement = elementPart(
  'div',
  'CodeBlock.Actions',
  'hj-code-block-actions',
);

export interface CodeOwnProps {
  /** Plain text. Highlighted and numbered for you; or pass already-highlighted children instead. */
  code?: string;
  /** Overrides the Root's language. */
  language?: string;
  /**
   * `true` uses the built-in highlighter (TS/JS/JSX, CSS, JSON, shell, HTML). Pass a function to
   * plug in Shiki or Prism, or `false` for plain text. Set it app-wide with HanjiProvider
   * `defaults={{ 'CodeBlock.Code': { highlight } }}`.
   * @default true
   */
  highlight?: boolean | Highlighter;
}
export interface CodeProps extends CodeOwnProps, React.ComponentProps<'pre'> {}

/**
 * The code. Focusable so keyboard users can scroll it; ⌘C / Ctrl+C with nothing selected copies
 * the whole block.
 */
export function Code(props: CodeProps): React.ReactElement {
  const [config, { code, language, highlight = true, className, children, onKeyDown, ...rest }] =
    useSlot('CodeBlock.Code', props);
  const { language: rootLanguage, lineNumbers, copy, setCode } = useCodeBlock('Code');
  const lang = language ?? rootLanguage;
  const tokens = useTokens(code, lang, highlight);
  const styled = !config.unstyled;
  let body: React.ReactNode = children;
  if (tokens && lineNumbers) {
    body = toLines(tokens).map((line, i) => (
      // oxlint-disable-next-line react/no-array-index-key -- lines are positional
      <span key={i} className={styled ? 'hj-code-block-line' : undefined}>
        {line.map((t, j) => paint(t, j, styled))}
        {'\n'}
      </span>
    ));
  } else if (tokens) {
    body = tokens.map((t, j) => paint(t, j, styled));
  }
  return (
    // oxlint-disable-next-line jsx-a11y/no-noninteractive-element-interactions -- ⌘C on a focusable scroll region is a shortcut; Copy stays the accessible path
    <pre
      // oxlint-disable-next-line jsx-a11y/no-noninteractive-tabindex -- a scroll region must be keyboard-reachable (WCAG 2.1.1)
      tabIndex={0}
      {...rest}
      data-language={lang}
      className={
        cls(config, 'CodeBlock.Code', 'hj-code-block-code', className) as string | undefined
      }
      onKeyDown={(e) => {
        onKeyDown?.(e);
        if (e.defaultPrevented || e.altKey || e.shiftKey || !(e.metaKey || e.ctrlKey)) return;
        if (e.key.toLowerCase() !== 'c') return;
        const selection = window.getSelection();
        if (selection && !selection.isCollapsed) return; // copy what the reader selected
        e.preventDefault();
        copy();
      }}
    >
      <code ref={setCode}>{body}</code>
    </pre>
  );
}

